frappe.ui.form.on('Supplier', {
  refresh: function(frm) {
    if (frm.doc.supplier_primary_contact) {
      frappe.db.get_value('Contact', frm.doc.supplier_primary_contact, ['mobile_no', 'email_id']).then(r => {
        if (r && r.message) {
          frm.set_value('mobile_no', r.message.mobile_no || '');
          frm.set_value('email_id', r.message.email_id || '');
        }
      });
    }
    if (frm.doc.supplier_primary_address) {
      frappe.db.get_value('Address', frm.doc.supplier_primary_address, ['address_line1', 'city', 'state', 'country']).then(r => {
        if (r && r.message) {
          const parts = [r.message.address_line1, r.message.city, r.message.state, r.message.country].filter(Boolean);
          frm.set_value('primary_address', parts.join(', '));
        }
      });
    }
  },
  supplier_primary_contact: function(frm) {
    if (frm.doc.supplier_primary_contact) {
      frappe.db.get_value('Contact', frm.doc.supplier_primary_contact, ['mobile_no', 'email_id']).then(r => {
        if (r && r.message) {
          frm.set_value('mobile_no', r.message.mobile_no || '');
          frm.set_value('email_id', r.message.email_id || '');
        }
      });
    }
  },
  supplier_primary_address: function(frm) {
    if (frm.doc.supplier_primary_address) {
      frappe.db.get_value('Address', frm.doc.supplier_primary_address, ['address_line1', 'city', 'state', 'country']).then(r => {
        if (r && r.message) {
          const parts = [r.message.address_line1, r.message.city, r.message.state, r.message.country].filter(Boolean);
          frm.set_value('primary_address', parts.join(', '));
        }
      });
    }
  }
});

