frappe.ui.form.on('Supplier', {
	custom_registry_registration_number: function(frm) {
		var reg = frm.doc.custom_registry_registration_number;
		if (!reg) {
			return;
		}
		frappe.call({
			method: 'frappe.client.get_value',
			args: {
				doctype: 'Regulatory Registry',
				filters: { registration_number: reg },
				fieldname: ['registration_number','legal_name','status','source','verified_on']
			},
			callback: function(r) {
				if(r.message) {
					frm.set_value('custom_registry_registration_number', r.message.registration_number);
					frm.set_value('custom_registry_source', r.message.source);
					frm.set_value('custom_registry_verified_on', r.message.verified_on);
					frm.set_value('custom_registry_verified', 1);
					if(!frm.doc.supplier_name && r.message.legal_name) {
						frm.set_value('supplier_name', r.message.legal_name);
					}
				} else {
					frm.set_value('custom_registry_verified', 0);
					frm.set_value('custom_registry_source', '');
					frm.set_value('custom_registry_verified_on', '');
					frappe.msgprint('No matching Regulatory Registry record found for ' + reg);
				}
			}
		});
	}
});

frappe.ui.form.on('Purchase Order', {
  refresh: function(frm) {
    if (frm.doc.docstatus === 1 && !frm.doc.custom_is_permit) {
      frm.add_custom_button('Convert to Permit', function() {
        frm.set_value('custom_is_permit', 1);
        frm.set_value('custom_permit_date', frappe.datetime.get_today());
        frm.set_value('custom_permit_by', frappe.session.user);
        frm.save().then(function() {
          frappe.msgprint('Converted to Permit. Use Print > Depot Permit (PO) to print.');
        });
      });
    }
