frappe.ui.form.on('Material Request Item', {
  item_code: function(frm, cdt, cdn) { scm_check_alternates(frm, cdt, cdn); },
  qty: function(frm, cdt, cdn) { scm_check_alternates(frm, cdt, cdn); }
});

function scm_check_alternates(frm, cdt, cdn) {
  var row = frappe.get_doc(cdt, cdn);
  var wh = row.warehouse || frm.doc.set_warehouse || frm.doc.set_from_warehouse;
  if (!row.item_code || !wh) { return; }
  frappe.db.get_value('Bin', { item_code: row.item_code, warehouse: wh }, 'actual_qty').then(function(r) {
    var needed = (row.qty || 0);
    var have = (r && r.message && r.message.actual_qty) ? r.message.actual_qty : 0;
    if (have >= needed && needed > 0) { return; }
    frappe.db.get_list('Item Alternative', { filters: { item_code: row.item_code }, fields: ['alternative_item'], limit: 10 }).then(function(alts) {
      if (!alts || alts.length === 0) { return; }
      var found = null;
      var checks = [];
      alts.forEach(function(a) {
        checks.push(
          frappe.db.get_value('Bin', { item_code: a.alternative_item, warehouse: wh }, 'actual_qty').then(function(rr) {
            var aq = (rr && rr.message && rr.message.actual_qty) ? rr.message.actual_qty : 0;
            if (!found && aq > 0) { found = a.alternative_item; }
          })
        );
      });
      Promise.all(checks).then(function() {
        if (found) {
          frappe.model.set_value(cdt, cdn, 'custom_alternate_item', found);
          frappe.msgprint({ title: 'Alternate Available', message: 'Alternate item ' + found + ' is available in ' + wh + '. It has been suggested in Alternate Item field.' });
        }
      });
    });
  });
}

frappe.ui.form.on('Supplier', {
	supplier_primary_contact: function(frm) {
		if (!frm.doc.supplier_primary_contact) {
			return;
		}
		frappe.db.get_value('Contact', frm.doc.supplier_primary_contact, ['full_name','mobile_no','phone']).then(r => {
			if (!r || !r.message) {
				return;
			}
			const msg = r.message;
			// fill name if not filled
			if (!frm.doc.custom_vendor_contact_name && (msg.full_name)) {
				frm.set_value('custom_vendor_contact_name', msg.full_name);
			}
			// try to fill mobile from Contact mobile_no or phone, strip non-digits
			if (!frm.doc.custom_vendor_contact_mobile) {
				let m = msg.mobile_no || msg.phone || '';
				if (m) {
					let digits = m.toString().replace(/\D/g, '');
					frm.set_value('custom_vendor_contact_mobile', digits);
				}
			}
		});
	},
	custom_vendor_contact_mobile: function(frm) {
		if (!frm.doc.custom_vendor_contact_mobile) return;
		// remove non-digits for user convenience
		let v = frm.doc.custom_vendor_contact_mobile.toString();
		let cleaned = v.replace(/\D/g, '');
		if (cleaned !== v) {
			frm.set_value('custom_vendor_contact_mobile', cleaned);
		}
	}
});
